package com.example.anotafacil.presentation.price_definition

import androidx.compose.ui.text.TextRange
import androidx.compose.ui.text.input.TextFieldValue
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.anotafacil.domain.formatter.brazilianCurrencyFormatter
import com.example.anotafacil.domain.formatter.parseBrazilianCurrencyInput
import com.example.anotafacil.domain.model.Product
import com.example.anotafacil.domain.repository.ProductRepository
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch
import javax.inject.Inject
import kotlin.uuid.Uuid

@HiltViewModel
class PriceDefinitionViewModel @Inject constructor(
    private val productRepository: ProductRepository
) : ViewModel() {

    private val _uiState = MutableStateFlow(PriceDefinitionUiState())
    val uiState = _uiState.asStateFlow()


    init {
        viewModelScope.launch {
            val products = productRepository.getAllProducts().map { product ->
                Product(
                    id = product.id,
                    name = product.name,
                    price = product.price
                )
            }
            _uiState.update { it.copy(items = products, originalItems = products) }
        }
    }

    fun addManualProduct() {
        val toBrazilianInput = parseBrazilianCurrencyInput(_uiState.value.manuelProductPrice.text)
        val product = Product(
            name = _uiState.value.manualProductName,
            price = toBrazilianInput.toInt(),
        )

        _uiState.update { uiState ->
            uiState.copy(
                items = uiState.items + product,
            )
        }
    }

    fun updateManualProductName(name: String) {
        _uiState.update { uiState ->
            uiState.copy(manualProductName = name)
        }
    }

    fun updateProductPrice(productId: Uuid, newPrice: String) {

        _uiState.update { uiState ->
            uiState.copy(
                items = uiState.items.map { product ->
                    if (product.id == productId)
                        product.copy(price = newPrice.toInt())
                    else
                        product
                }
            )
        }
    }


    fun updateManualProductPrice(newPrice: String) {

        val toBrazilianInput = parseBrazilianCurrencyInput(newPrice)
        val visualFormatText = brazilianCurrencyFormatter.format(toBrazilianInput)

        _uiState.update { uiState ->
            uiState.copy(
                manuelProductPrice = TextFieldValue(
                    visualFormatText,
                    selection = TextRange(visualFormatText.length)
                )
            )
        }
    }


    fun dismissPriceSaved() {
        _uiState.update { it.copy(priceSaved = false) }
    }

    fun savePrices() {
        _uiState.update { it.copy(isLoading = true) }
        viewModelScope.launch {
            var result = false

            _uiState.value.items.forEach { product ->
                if (product.price == 0) return@forEach
                result = productRepository.saveProductChanges(product)
            }

            if (result) {
                _uiState.update { uiState ->
                    uiState.copy(
                        originalItems = uiState.items,
                        isLoading = false,
                        priceSaved = true,
                    )
                }
            }
        }
    }
}

data class PriceDefinitionUiState(
    val items: List<Product> = emptyList(),
    val originalItems: List<Product> = emptyList(),
    val manualProductName: String = "",
    val manuelProductPrice: TextFieldValue = TextFieldValue("R$ 0,00"),
    val itemPrice: String = "",
    val priceSaved: Boolean = false,
    val isLoading: Boolean = false
) {
    val hasChanges: Boolean
        get() = items.size > originalItems.size
}

package com.example.anotafacil.presentation.price_definition

import androidx.compose.ui.text.TextRange
import androidx.compose.ui.text.input.TextFieldValue
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.anotafacil.domain.formatter.brazilianCurrencyFormatter
import com.example.anotafacil.domain.formatter.parseBrazilianCurrencyInput
import com.example.anotafacil.domain.model.Product
import com.example.anotafacil.domain.repository.ProductRepository
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch
import javax.inject.Inject
import kotlin.uuid.Uuid

@HiltViewModel
class PriceDefinitionViewModel @Inject constructor(
    private val productRepository: ProductRepository
) : ViewModel() {

    private val _uiState = MutableStateFlow(PriceDefinitionUiState())
    val uiState = _uiState.asStateFlow()


    init {
        viewModelScope.launch {
            val products = productRepository.getAllProducts().map { product ->
                Product(
                    id = product.id,
                    name = product.name,
                    price = product.price
                )
            }
            _uiState.update { it.copy(items = products, originalItems = products) }
        }
    }

    fun addManualProduct() {
        val productName = _uiState.value.manualProductName.trim()
        if (productName.isBlank()) return

        val toBrazilianInput = parseBrazilianCurrencyInput(_uiState.value.manuelProductPrice.text)
        val product = Product(
            name = productName,
            price = toBrazilianInput.toInt(),
        )

        _uiState.update { uiState ->
            uiState.copy(
                items = listOf(product) + uiState.items,
                manualProductName = "",
                manuelProductPrice = TextFieldValue("R$ 0,00")
            )
        }
    }

    fun updateManualProductName(name: String) {
        _uiState.update { uiState ->
            uiState.copy(manualProductName = name)
        }
    }

    fun updateProductPrice(productId: Uuid, newPrice: String) {

        _uiState.update { uiState ->
            uiState.copy(
                items = uiState.items.map { product ->
                    if (product.id == productId)
                        product.copy(price = newPrice.toInt())
                    else
                        product
                }
            )
        }
    }


    fun updateManualProductPrice(newPrice: String) {

        val toBrazilianInput = parseBrazilianCurrencyInput(newPrice)
        val visualFormatText = brazilianCurrencyFormatter.format(toBrazilianInput)

        _uiState.update { uiState ->
            uiState.copy(
                manuelProductPrice = TextFieldValue(
                    visualFormatText,
                    selection = TextRange(visualFormatText.length)
                )
            )
        }
    }


    fun dismissPriceSaved() {
        _uiState.update { it.copy(priceSaved = false) }
    }

    fun savePrices() {
        _uiState.update { it.copy(isLoading = true) }
        viewModelScope.launch {
            var result = false

            _uiState.value.items.forEach { product ->
                if (product.price == 0) return@forEach
                result = productRepository.saveProductChanges(product)
            }

            if (result) {
                _uiState.update { uiState ->
                    uiState.copy(
                        originalItems = uiState.items,
                        isLoading = false,
                        priceSaved = true,
                    )
                }
            }
        }
    }
}

data class PriceDefinitionUiState(
    val items: List<Product> = emptyList(),
    val originalItems: List<Product> = emptyList(),
    val manualProductName: String = "",
    val manuelProductPrice: TextFieldValue = TextFieldValue("R$ 0,00"),
    val itemPrice: String = "",
    val priceSaved: Boolean = false,
    val isLoading: Boolean = false
) {
    val hasChanges: Boolean
        get() = items.size > originalItems.size
}

package com.example.anotafacil.data.dao
import androidx.room.Dao import androidx.room.Insert import androidx.room.OnConflictStrategy import androidx.room.Query import androidx.room.Transaction import androidx.room.Update import com.example.anotafacil.data.entity.CartItemEntity import com.example.anotafacil.data.entity.PurchaseEntity import com.example.anotafacil.domain.model.MonthlySalesData import com.example.anotafacil.domain.model.PurchaseWithItemsData import com.example.anotafacil.domain.model.SyncStatus import kotlinx.coroutines.flow.Flow import kotlin.uuid.Uuid
@Dao interface PurchaseDao { @Update suspend fun updatePurchase(purchase: PurchaseEntity): Int
@Insert(onConflict = OnConflictStrategy.REPLACE) suspend fun addPurchase(purchase: PurchaseEntity)
@Transaction @Query(""" SELECT * FROM purchase WHERE customerId = :customerId ORDER BY id DESC LIMIT 1 """) fun getLastPurchase(customerId: Uuid?): Flow<PurchaseWithItemsData?>
@Transaction @Query(""" SELECT * FROM purchase WHERE customerId = :customerId ORDER BY purchaseDate DESC """) fun getAllPurchases(customerId: Uuid?): Flow<List<PurchaseWithItemsData>>
@Query(""" SELECT strftime( '%Y-%m', datetime( p.purchaseDate / 1000, 'unixepoch', 'localtime' ) ) AS month,
SUM(ci.quantity) AS totalQuantity
FROM purchase AS p
INNER JOIN cart_item AS ci ON ci.purchaseId = p.id
WHERE p.purchaseDate >= :startDate AND p.purchaseDate < :endDate
GROUP BY month
ORDER BY month ASC """) fun getMonthlySales( startDate: Long, endDate: Long ): Flow<List<MonthlySalesData>>
@Query(""" UPDATE purchase SET syncStatus = :status WHERE id = :purchaseId """) suspend fun updateSyncStatus( purchaseId: Uuid, status: SyncStatus ): Int
@Transaction @Query(""" SELECT * FROM purchase WHERE syncStatus = :status ORDER BY purchaseDate ASC """) suspend fun getPurchasesBySyncStatus( status: SyncStatus ): List<PurchaseWithItemsData>
@Query(""" SELECT * FROM purchase WHERE id = :purchaseId """) suspend fun getPurchaseById( purchaseId: Uuid ): PurchaseEntity?
@Query("DELETE FROM purchase") suspend fun deleteAll()
@Query("DELETE FROM cart_item") suspend fun deleteAllCartItems() }

package com.example.anotafacil.data.dao
import androidx.room.Dao import androidx.room.Insert import androidx.room.OnConflictStrategy import androidx.room.Query import androidx.room.Transaction import androidx.room.Update import com.example.anotafacil.data.entity.CartItemEntity import com.example.anotafacil.data.entity.PurchaseEntity import com.example.anotafacil.domain.model.MonthlySalesData import com.example.anotafacil.domain.model.PurchaseWithItemsData import com.example.anotafacil.domain.model.SyncStatus import kotlinx.coroutines.flow.Flow import kotlin.uuid.Uuid
@Dao interface PurchaseDao { @Update suspend fun updatePurchase(purchase: PurchaseEntity): Int
@Insert(onConflict = OnConflictStrategy.REPLACE) suspend fun addPurchase(purchase: PurchaseEntity)
@Transaction @Query(""" SELECT * FROM purchase WHERE customerId = :customerId ORDER BY id DESC LIMIT 1 """) fun getLastPurchase(customerId: Uuid?): Flow<PurchaseWithItemsData?>
@Transaction @Query(""" SELECT * FROM purchase WHERE customerId = :customerId ORDER BY purchaseDate DESC """) fun getAllPurchases(customerId: Uuid?): Flow<List<PurchaseWithItemsData>>
@Query(""" SELECT months.month, COALESCE(( SELECT SUM(p.totalAmount) FROM purchase AS p LEFT JOIN customer AS c ON c.id = p.customerId WHERE strftime('%Y-%m', datetime(p.purchaseDate / 1000, 'unixepoch', 'localtime')) = months.month AND p.purchaseDate >= :startDate AND p.purchaseDate < :endDate AND (:cityId IS NULL OR c.cityId = :cityId) ), 0) AS totalSales, COALESCE(( SELECT SUM(pay.amount) FROM payment AS pay LEFT JOIN customer AS c ON c.id = pay.customerId WHERE strftime('%Y-%m', datetime(pay.paymentDate / 1000, 'unixepoch', 'localtime')) = months.month AND pay.paymentDate >= :startDate AND pay.paymentDate < :endDate AND (:cityId IS NULL OR c.cityId = :cityId) ), 0) AS totalReceived, COALESCE(( SELECT SUM(ci.quantity) FROM cart_item AS ci INNER JOIN purchase AS p ON p.id = ci.purchaseId LEFT JOIN customer AS c ON c.id = p.customerId WHERE strftime('%Y-%m', datetime(p.purchaseDate / 1000, 'unixepoch', 'localtime')) = months.month AND p.purchaseDate >= :startDate AND p.purchaseDate < :endDate AND (:cityId IS NULL OR c.cityId = :cityId) ), 0) AS totalProducts FROM ( SELECT DISTINCT strftime('%Y-%m', datetime(purchaseDate / 1000, 'unixepoch', 'localtime')) AS month FROM purchase WHERE purchaseDate >= :startDate AND purchaseDate < :endDate UNION SELECT DISTINCT strftime('%Y-%m', datetime(paymentDate / 1000, 'unixepoch', 'localtime')) AS month FROM payment WHERE paymentDate >= :startDate AND paymentDate < :endDate ) AS months ORDER BY months.month ASC """) fun getMonthlySales( startDate: Long, endDate: Long, cityId: Uuid? = null ): Flow<List<MonthlySalesData>>
@Query(""" UPDATE purchase SET syncStatus = :status WHERE id = :purchaseId """) suspend fun updateSyncStatus( purchaseId: Uuid, status: SyncStatus ): Int
@Transaction @Query(""" SELECT * FROM purchase WHERE syncStatus = :status ORDER BY purchaseDate ASC """) suspend fun getPurchasesBySyncStatus( status: SyncStatus ): List<PurchaseWithItemsData>
@Query(""" SELECT * FROM purchase WHERE id = :purchaseId """) suspend fun getPurchaseById( purchaseId: Uuid ): PurchaseEntity?
@Query("DELETE FROM purchase") suspend fun deleteAll()
@Query("DELETE FROM cart_item") suspend fun deleteAllCartItems() }

package com.example.anotafacil.data.repository

